ser_id, s.owner_name) },\n                repo_alias: s.repo_alias,\n                harness: s.harness,\n                // When it started: with the key's end, it tells one person's sessions in one repository apart (W3).\n                started_at: s.started_at,\n                state: s.state,\n                agent_stopped: !!s.agent_stopped,\n                stop_status: stopStatus(pp.wsId, s.session_key),\n            }))\n            : null;\n        return { mine, all: everyone };\n    }\n    return { endSessions, sessionRow, openEpoch, ownSession, putSession, openBindingEpoch, USAGE_FIELDS, ingestUsage, stopSharing, deleteSession, setAgentStop, listSessions };\n}\nmodule.exports = { create_sessions };\n","server_sessions/package.json":"{\"name\":\"server_sessions\",\"type\":\"commonjs\",\"exports\":{\"./create_sessions\":\"./create_sessions.js\"}}\n"},root=fs.mkdtempSync(path.join(os.tmpdir(),'owned-goals-reference-'));for(const [name,body]of Object.entries(privateFiles)){const file=path.join(root,name);fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,body);}verifier.runSelected(root,null,selected).then(cases=>console.log(JSON.stringify(cases[0].result))).catch(error=>{console.error(error.stack);process.exitCode=1;}).finally(()=>fs.rmSync(root,{recursive:true,force:true}));
